-- 2026 NCAA Division I football rosters: one table per team
-- Source workbook: 5e017105-06c4-484c-8c78-06269ea3eb7c.xlsx
-- Snapshot date: 2026-09-09
-- Team tables: 266; players: 29613
-- Table names use the full team name with underscores.

SET NAMES utf8mb4;

CREATE DATABASE IF NOT EXISTS `college_football_data`
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

USE `college_football_data`;

CREATE TABLE IF NOT EXISTS `team_table_directory` (
  `table_name` VARCHAR(64) NOT NULL,
  `team_id` INT UNSIGNED NOT NULL,
  `season` SMALLINT UNSIGNED NOT NULL,
  `subdivision` VARCHAR(10) NOT NULL,
  `team_name` VARCHAR(150) NOT NULL,
  `school` VARCHAR(150) NOT NULL,
  `abbreviation` VARCHAR(20) NULL,
  `player_count` SMALLINT UNSIGNED NOT NULL,
  `roster_source` VARCHAR(500) NULL,
  `source_timestamp` DATETIME NULL,
  `source_date` DATE NULL,
  `snapshot_date` DATE NOT NULL,
  `worksheet_name` VARCHAR(100) NOT NULL,
  PRIMARY KEY (`table_name`),
  UNIQUE KEY `uq_team_season` (`team_id`, `season`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `Air_Force_Falcons` (
  `team_id` INT UNSIGNED NOT NULL,
  `season` SMALLINT UNSIGNED NOT NULL,
  `subdivision` VARCHAR(10) NOT NULL,
  `athlete_id` BIGINT UNSIGNED NOT NULL,
  `jersey` VARCHAR(10) NULL,
  `full_name` VARCHAR(150) NOT NULL,
  `first_name` VARCHAR(100) NULL,
  `last_name` VARCHAR(100) NULL,
  `position` VARCHAR(10) NULL,
  `position_name` VARCHAR(100) NULL,
  `position_group` VARCHAR(50) NULL,
  `roster_group` VARCHAR(50) NULL,
  `class_name` VARCHAR(30) NULL,
  `class_abbreviation` VARCHAR(10) NULL,
  `experience_years` TINYINT UNSIGNED NULL,
  `height_display` VARCHAR(20) NULL,
  `height_inches` SMALLINT UNSIGNED NULL,
  `weight_lbs` SMALLINT UNSIGNED NULL,
  `display_weight` VARCHAR(20) NULL,
  `hometown` VARCHAR(200) NULL,
  `birth_city` VARCHAR(150) NULL,
  `birth_state` VARCHAR(100) NULL,
  `birth_country` VARCHAR(100) NULL,
  `status` VARCHAR(50) NULL,
  `status_type` VARCHAR(50) NULL,
  `injuries` TEXT NULL,
  `listed_college` VARCHAR(150) NULL,
  `player_page` VARCHAR(500) NULL,
  `headshot_url` VARCHAR(500) NULL,
  PRIMARY KEY (`season`, `athlete_id`),
  KEY `idx_player_name` (`last_name`, `first_name`),
  KEY `idx_player_position` (`position`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

